"use strict";
(()=>{
 const D=window.LEARNWITHUS_ENGLISH_UPGRADE,root=document.getElementById('englishQuizRoot');if(!D||!root)return;const qs=new URLSearchParams(location.search),topic=D.meta[qs.get('topic')]?qs.get('topic'):'sight-words',meta=D.meta[topic];
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const norm=s=>String(s||'').toLowerCase().replace(/[^a-z0-9\s]/g,'').replace(/\s+/g,' ').trim();const shuffle=a=>[...a].sort(()=>Math.random()-.5);const speak=text=>{if(!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-IN';u.rate=.78;window.speechSynthesis.speak(u)};
 document.title=meta.title+' Quiz | LearnWithUs';document.getElementById('englishQuizTitle').textContent=meta.icon+' '+meta.title+' Quiz';document.getElementById('englishQuizDeck').textContent=topic==='reading-coach'?'Read five sentences aloud. Speech recognition is used when available; a typing fallback is provided when it is not.':'Ten focused questions from the '+meta.title+' learning activity.';
 function options(q,a,opts,extra=''){return{type:'choice',q,a,opts,extra}};const pools={
 'sight-words':D.sightWords.map(([w,s])=>options(`Which word completes the sentence? “${s.replace(new RegExp('\\b'+w+'\\b','i'),'___')}”`,w,[w,...shuffle(D.sightWords.map(x=>x[0]).filter(x=>x!==w)).slice(0,3)])),
 'word-families':Object.entries(D.families).flatMap(([f,words])=>words.map(w=>options(`Which word belongs to the ${f} family?`,w,[w,...shuffle(Object.entries(D.families).filter(([k])=>k!==f).flatMap(([,v])=>v)).slice(0,3)]))),
 'rhyming-words':D.rhymes.map(([a,b])=>options(`Which word rhymes with “${a}”?`,b,[b,...shuffle(D.rhymes.filter(x=>!x.includes(b)).flat()).slice(0,3)])),
 'opposites':D.opposites.map(([a,b])=>options(`What is the opposite of “${a}”?`,b,[b,...shuffle(D.opposites.filter(x=>!x.includes(b)).flat()).slice(0,3)])),
 'sentence-builder':D.sentences.map(s=>{const words=s.match(/[A-Za-z’]+|[.!?]/g),core=words.filter(w=>!/[.!?]/.test(w)),punct=words.find(w=>/[.!?]/.test(w))||'.',bad1=[...core].reverse().join(' ')+' '+punct,bad2=core.slice(1).concat(core[0]).join(' ')+' '+punct,bad3=(core.length>2?[core[1],core[0],...core.slice(2)]:[...core].reverse()).join(' ')+' '+punct;return options('Which sentence is written in the correct order?',s,[s,bad1.replace(/\s+([.!?])/g,'$1'),bad2.replace(/\s+([.!?])/g,'$1'),bad3.replace(/\s+([.!?])/g,'$1')])}),
 'grammar':D.grammar.map(g=>options(g.q,g.answer,g.choices,`<span class="english-quiz-topic">${esc(g.concept)}</span><p>${esc(g.rule)}</p>`)),
 'reading-comprehension':D.passages.flatMap(p=>p.questions.map(q=>options(q[0],q[2],q[1],`<span class="english-level-badge">${esc(p.level)}</span><h3>${esc(p.title)}</h3><p>${esc(p.text)}</p>`))),
 'dictation':D.dictation.map(x=>({type:'typed',q:'Listen, then type exactly what you hear.',a:x,spoken:x})),
 };
 let items=topic==='reading-coach'?shuffle(D.coach).slice(0,5):shuffle(pools[topic]||pools['sight-words']).slice(0,10),i=0,score=0,locked=false,total=items.length;
 function finish(){root.innerHTML=`<section class="practice-box"><p class="game-progress">Quiz complete</p><p class="game-question">${score} / ${total}</p><p class="game-feedback">${score===total?'Excellent work!':'Good effort. Review the learning page and try again.'}</p><div id="sharedScoreCard"></div><div class="journey-actions"><button class="practice-button journey-primary" id="again" type="button">Play again</button><a class="practice-button journey-secondary" href="english-skills.html?topic=${topic}">← Review ${esc(meta.title)}</a><a class="practice-button journey-secondary" href="quiz-hub.html">Quiz Hub →</a></div></section>`;window.renderLearnWithUsScoreCard?.({container:document.getElementById('sharedScoreCard'),score,total,title:meta.title+' Quiz',subtitle:'English & Reading practice on LearnWithUs.',filename:'learnwithus-'+topic+'-score.svg',url:'english-skills-quiz.html?topic='+topic});window.LearnWithUs?.recordQuiz?.(meta.title+' quiz',score,total,'english-skills-quiz.html?topic='+topic);document.getElementById('again').onclick=()=>location.reload()}
 function sayResult(ok,a){const msg=ok?'Correct answer! It is '+a+'.':'Wrong answer. The correct answer is '+a+'.';document.getElementById('quizFeedback').textContent=msg;speak(msg);if(ok)score++;document.getElementById('quizNext').hidden=false}
 function choice(item){root.innerHTML=`<section class="practice-box"><p class="game-progress">Question ${i+1} of ${total}</p>${item.extra?`<div class="english-quiz-visual">${item.extra}</div>`:''}<p class="game-question">${esc(item.q)}</p><div class="game-options" id="quizOptions"></div><p class="game-feedback" id="quizFeedback" role="status" aria-live="polite"></p><button class="practice-button game-next" id="quizNext" hidden>${i===total-1?'See score →':'Next →'}</button></section>`;const row=document.getElementById('quizOptions');shuffle(item.opts).forEach(v=>{const b=document.createElement('button');b.type='button';b.textContent=v;b.onclick=()=>{if(locked)return;locked=true;row.querySelectorAll('button').forEach(x=>{x.disabled=true;if(x.textContent===item.a)x.classList.add('correct')});b.classList.add(v===item.a?'correct':'wrong');window.LWUSmart?.recordAnswer?.(item.q,v,item.a,{title:meta.title+' Quiz',url:'english-skills-quiz.html?topic='+topic,category:'English'});sayResult(v===item.a,item.a)};row.append(b)});document.getElementById('quizNext').onclick=()=>{i++;round()}}
 function typed(item){root.innerHTML=`<section class="practice-box"><p class="game-progress">Question ${i+1} of ${total}</p><p class="game-question">${esc(item.q)}</p><button class="practice-button journey-secondary" id="hearTyped" type="button">🔊 Hear prompt</button><div class="skill-toolbar"><label>Your answer<input class="english-quiz-text-input" id="typedAnswer" autocomplete="off"></label></div><button class="practice-button journey-primary" id="checkTyped" type="button">Check answer</button><p class="game-feedback" id="quizFeedback" role="status" aria-live="polite"></p><button class="practice-button game-next" id="quizNext" hidden>${i===total-1?'See score →':'Next →'}</button></section>`;speak('Listen and type. '+item.spoken);document.getElementById('hearTyped').onclick=()=>speak(item.spoken);document.getElementById('checkTyped').onclick=()=>{if(locked)return;locked=true;window.LWUSmart?.recordAnswer?.(item.q,document.getElementById('typedAnswer').value,item.a,{title:meta.title+' Quiz',url:'english-skills-quiz.html?topic='+topic,category:'English'});sayResult(norm(document.getElementById('typedAnswer').value)===norm(item.a),item.a)};document.getElementById('quizNext').onclick=()=>{i++;round()}}
 function coach(sentence){const Rec=window.SpeechRecognition||window.webkitSpeechRecognition;root.innerHTML=`<section class="practice-box"><p class="game-progress">Reading ${i+1} of ${total}</p><p class="game-question">Read this sentence aloud</p><div class="coach-line">${esc(sentence)}</div><div class="reading-coach-controls"><button class="practice-button journey-secondary" id="hearCoachQuiz">🔊 Hear model</button><button class="practice-button journey-primary" id="startCoachQuiz">🎙️ Start microphone</button></div><p class="mic-status" id="coachQuizStatus"></p><div id="coachFallback" ${Rec?'hidden':''}><p>Your browser does not provide speech recognition. Type the sentence as a fallback check.</p><input class="english-quiz-text-input" id="coachTyped"><button class="practice-button journey-primary" id="coachTypedCheck">Check typed sentence</button></div><p class="game-feedback" id="quizFeedback" role="status" aria-live="polite"></p><button class="practice-button game-next" id="quizNext" hidden>${i===total-1?'See score →':'Next →'}</button></section>`;document.getElementById('hearCoachQuiz').onclick=()=>speak(sentence);const done=(ok,heard)=>{if(locked)return;locked=true;const msg=ok?'Great reading! Most words matched.':'Good try. The target sentence is '+sentence;document.getElementById('quizFeedback').textContent=(heard?'Heard: '+heard+'. ':'')+msg;speak(msg);if(ok)score++;document.getElementById('quizNext').hidden=false};if(Rec){document.getElementById('coachQuizStatus').textContent='Microphone feedback is available. No recording is saved by LearnWithUs.';document.getElementById('startCoachQuiz').onclick=()=>{const r=new Rec();r.lang='en-IN';r.interimResults=false;r.onresult=e=>{const heard=e.results[0][0].transcript,t=norm(sentence).split(' '),h=new Set(norm(heard).split(' ')),pct=Math.round(t.filter(w=>h.has(w)).length/t.length*100);done(pct>=80,heard)};r.onerror=()=>document.getElementById('coachQuizStatus').textContent='I could not hear that clearly. Try again.';r.start()}}else{document.getElementById('startCoachQuiz').disabled=true;document.getElementById('coachQuizStatus').textContent='Speech recognition is not supported here; use the typing fallback.';document.getElementById('coachTypedCheck').onclick=()=>done(norm(document.getElementById('coachTyped').value)===norm(sentence),'')};document.getElementById('quizNext').onclick=()=>{i++;round()}}
 function round(){if(i>=total)return finish();locked=false;const item=items[i];if(topic==='reading-coach')coach(item);else if(item.type==='typed')typed(item);else choice(item)}round();
})();
